const order = $input.first().json.body || $input.first().json;
const items = (order.items || []).map(i => `• ${i.chaussureNom} x${i.quantity}${i.pointure ? ' (P'+i.pointure+')' : ''}`).join('\n');
const canal = order.canalFinalisation === 'WHATSAPP' ? '💬 WhatsApp' : '🌐 Web';
return [{
  json: {
    ...order,
    items_text: items,
    canal_label: canal,
    total_fmt: Number(order.total || 0).toLocaleString('fr-FR') + ' FCFA'
  }
}];

